def other_template(kb):
    """Off-topic questions. Topic list comes from kb.json, so it follows the KB."""
    topics = ", ".join(d["title"].lower() for d in kb[:6])
    return (
        "Thanks for reaching out! I can only help with questions about our "
        f"products and your account, for example: {topics}. Could you tell me a "
        "bit more about what you need? You can also contact our support team "
        "at any time."
    )
